def rounded_avg(n,m):
    """You are given two positive integers n and m, ..."""
    if n > m:
        return -1
    total = sum(range(n, m+1))
    avg_rounded = round(total / (m-n + 1))
    # Convert to binary string with '0b' prefix.
    return bin(avg_rounded)

