def find_zero(xs: list):
    lo = -1.0
    hi = 1.0
    for _ in range(200):
        if poly(xs, lo) == 0:
            return lo
        if poly(xs, hi) == 0:
            return hi
        if poly(xs, lo) * poly(xs, hi) < 0:
            break
        lo *= 2
        hi *= 2
    for _ in range(200):
        mid = (lo + hi) / 2.0
        if poly(xs, mid) == 0:
            return mid
        if poly(xs, lo) * poly(xs, mid) <= 0:
            hi = mid
        else:
            lo = mid
    return (lo + hi) / 2.0

