def prod_signs(arr):
    if not arr:
        return None
    signs = [1 if x > 0 else -1 if x < 0 else 0 for x in arr]
    product_of_signs = 1
    for s in signs:
        if s == 0:
            return 0
        product_of_signs *= s
    magnitude_sum = sum(abs(x) for x in arr)
    return magnitude_sum * product_of_signs

