def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    result = []
    vowels = "aeiouAEIOU"
    for char in message:
        if char.isalpha():
            if char.islower():
                if char in vowels:
                    next_char_code = ord(char) + 2
                    if next_char_code <= ord('z'):
                        result.append(chr(next_char_code))
                    else:
                        result.append(char)
                else:
                    result.append(char.upper())
            else:
                if char in vowels:
                    next_char_code = ord(char) + 2
                    if next_char_code <= ord('Z'):
                        result.append(chr(next_char_code))
                    else:
                        result.append(char)
                else:
                    result.append(char.lower())
        else:
            result.append(char)
    return "".join(result)

