def minPath(grid, k):
    N = len(grid)
    min_path_values = None

    def is_valid(r, c):
        return 0 <= r < N and 0 <= c < N

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                neighbors.append((nr, nc))
        return neighbors

    def compare_paths(path1, path2):
        for i in range(len(path1)):
            if path1[i] < path2[i]:
                return True  # path1 is lexicographically smaller
            if path1[i] > path2[i]:
                return False # path2 is lexicographically smaller
        return False # paths are equal (should not happen based on problem statement)

    for start_r in range(N):
        for start_c in range(N):
            # DFS to find all paths of length k starting from (start_r, start_c)
            stack = [(start_r, start_c, [grid[start_r][start_c]])]

            while stack:
                r, c, current_path = stack.pop()

                if len(current_path) == k:
                    if min_path_values is None or compare_paths(current_path, min_path_values):
                        min_path_values = list(current_path)
                    continue

                # Explore neighbors for the next step
                for nr, nc in get_neighbors(r, c):
                    new_path = current_path + [grid[nr][nc]]
                    stack.append((nr, nc, new_path))

    return min_path_values

