        mod_counts[val % 3] += 1
    count = 0
    # Triples where all three have the same remainder: C(cnt, 3)
    for c in mod_counts:
        if c >= 3:
            count += c * (c - 1) * (c - 2) // 6
    # Triples with two of one remainder and one of another: 3 * cnt[rem] * sum_{r != rem} cnt[r]
