        right = (i + 1) < n and word[i+1].lower() in vowels
        if left or right:
            return word[i]
    return ""

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    indexed = list(enumerate(nums))
    sorted_indexed = sorted(indexed, key=lambda x: (digit_sum(x[1]), x[0]))
    result = [num for _, num in sorted_indexed]
    return result

def intersection(interval1, interval2):
    s1, e1 = interval1
    s2, e2 = interval2
    start = max(s1, s2)
    end = min(e1, e2)
    length = end - start
    if length <= 0:
        return "NO"
    if length < 2:
        return "NO"
    for i in range(2, int(length**0.5) + 1):
        if length % i == 0:
            return "NO"
    return "YES"

def sum_squares(lst):
    total = 0
    for i, num in enumerate(lst):
        if i % 3 == 0:
            total += num ** 2
        elif i % 4 == 0:
            total += num ** 3
    return total

def generate_integers(a, b):
    lo, hi = min(a, b), max(a, b)
    return [d for d in range(0, 9, 2) if lo <= d <= hi]

def exchange(lst1, lst2):
    odd_in_lst1 = [x for x in lst1 if x % 2 != 0]
    even_in_lst2 = [x for x in lst2 if x % 2 == 0]

    return len(odd_in_lst1) <= len(even_in_lst2)

def split_words(txt):
    # Detect presence of any whitespace character in txt
    has_whitespace = any(c.isspace() for c in txt)

    if has_whitespace:
        # Split on whitespace (default str.split behavior)
        return txt.split()
    elif ',' in txt:
        # No whitespace but commas present: split on commas
        return txt.split(',')
    else:
        # Count lower-case letters with odd alphabetical index.
        count = 0
        for ch in txt:
            if 'a' <= ch <= 'z':
                # ord('a') is 97; mapping described as (ord(ch) - 97)
                if ((ord(ch) - 97) % 2 == 1):
                    count += 1
        return count

def is_sorted(lst):
    if len(set(lst)) != len(lst):
        return False
    return all(lst[i] <= lst[i+1] for i in range(len(lst)-1))

def encrypt(s):
    result = []
    for c in s:
        if 'a' <= c <= 'z':
            shifted = chr((ord(c) - ord('a') + 4) % 26 + ord('a'))
            result.append(shifted)
        else:
            result.append(c)
    return ''.join(result)

def count_nums(arr):
    count = 0
    for num in arr:
        if num == 0:
            continue
        sign = 1 if num >= 0 else -1
        digits = str(abs(num))
        total = int(digits[0]) + sum(int(d) for d in digits[1:])
        if total > 0:
            count += 1
    return count

