from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    s = ''.join(paren_string.split())
    result = []
    stack = []
    current = ''
    for ch in s:
        if ch == '(':
            stack.append(current)
            current = ''
        elif ch == ')':
            stack.pop()
            current += '(' + current + ')'
        else:
            current += ch
    if stack:
        result.append(stack.pop())
    result.append(current)
    return result

from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current = []
    depth = 0
    for char in paren_string:
        if char == ' ':
            continue
        if char == '(':
            depth += 1
            current.append(char)
        elif char == ')':
            depth -= 1
            current.append(char)
            if depth == 0:
                result.append(''.join(current))
                current = []
    return result

def derivative(xs: list):
    if len(xs) <= 1:
        return []
    return [xs[i] * (i + 1) for i in range(len(xs) - 1)]

